/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int calculateDepth(TreeNode* root) {
        if (!root) {
            return 0;
        }
        return 1 + max(calculateDepth(root->left), calculateDepth(root->right));
    }
};
